function parseDetailUrl(currentUrl) {
  var raw = '';
  if (currentUrl.indexOf('/wiki/') !== -1) {
    raw = currentUrl.split('/wiki/')[1];
  } else if (currentUrl.indexOf('titles=') !== -1) {
    var match = currentUrl.match(/titles=([^&]+)/i);
    if (match) raw = match[1];
  } else {
    var match = currentUrl.match(/(?:File:)?([^?#&]+)/i);
    if (match) raw = match[1];
  }
  raw = (raw || '').split(/[?#&]/)[0];
  try { raw = decodeURIComponent(raw); } catch (e) {}
  raw = raw.replace(/^(?:File[:%3A]|文件[:%3A])+/i, '').trim();
  var fileTitle = 'File:' + raw.replace(/_/g, ' ');
  var cleanTitle = raw.replace(/_/g, ' ').replace(/\.[a-z0-9]+$/i, '');
  return { fileTitle, cleanTitle };
}

